import sys, time, collections
import numpy as np
sys.path.append('/agent')
from test_cache import gen_ops

class LRUCachePython:
    __slots__ = ('capacity', 'od')
    def __init__(self, capacity: int):
        self.capacity = capacity
        self.od = collections.OrderedDict()
    def get(self, key: int) -> int:
        try:
            val = self.od.pop(key)
            self.od[key] = val
            return val
        except KeyError:
            return -1
    def put(self, key: int, value: int) -> None:
        # if key exists, update and move to end
        try:
            self.od.pop(key)
        except KeyError:
            if len(self.od) >= self.capacity:
                # evict LRU
                self.od.popitem(last=False)
        self.od[key] = value
    def run_ops(self, ops):
        results = []
        for is_put, key, val in ops:
            if is_put:
                self.put(key, val)
            else:
                results.append(self.get(key))
        # return as bytes of int64
        arr = np.array(results, dtype=np.int64)
        return arr.tobytes()

n = 8_000_000
capacity = 10_000
ops = gen_ops(n, capacity, 99)

c = LRUCachePython(capacity)
start = time.perf_counter()
c.run_ops(ops)
print('time python orderdict', time.perf_counter() - start)
